const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const raw = String((($('Find Client Folder Webhook').first().json.body) || {}).name || '').trim();
const wanted = norm(raw);
const folders = $input.all().map(i => i.json);
if (!wanted) return [{ json: { folderId: null, folderName: null, webViewLink: null, matchCount: 0 } }];

// Tier 1: exact match after stripping spaces/punctuation (handles "Thirdthursday" vs "Third Thursdays").
let candidates = folders.filter(f => norm(f.name) === wanted);
// Tier 2: containment either direction (handles partial names like "Tribe" in "Tribe Development City").
if (!candidates.length) candidates = folders.filter(f => { const n = norm(f.name); return n.indexOf(wanted) > -1 || wanted.indexOf(n) > -1; });

if (candidates.length === 1) {
  const f = candidates[0];
  return [{ json: { folderId: f.id, folderName: f.name, webViewLink: f.webViewLink || null, matchCount: 1 } }];
}
// Tier 3: multiple containment matches — only resolve if one is unambiguously the closest length match.
if (candidates.length > 1) {
  const byCloseness = [...candidates].sort((a, b) => Math.abs(norm(a.name).length - wanted.length) - Math.abs(norm(b.name).length - wanted.length));
  const best = byCloseness[0], second = byCloseness[1];
  if (Math.abs(norm(best.name).length - wanted.length) < Math.abs(norm(second.name).length - wanted.length)) {
    return [{ json: { folderId: best.id, folderName: best.name, webViewLink: best.webViewLink || null, matchCount: 1 } }];
  }
}
return [{ json: { folderId: null, folderName: null, webViewLink: null, matchCount: candidates.length } }];

